initial_aveh = [Init.aChassis.Value(3) Init.aChassis.Value(2) Init.aChassis.Value(1)];
rotmat_ypr = sm_car_yawpitchroll_to_rotmat(Init.aChassis.Value(3),Init.aChassis.Value(2),Init.aChassis.Value(1));
initial_vveh = rotmat_ypr*(Init.vChassis.Value)';

sptState = get_param(gcb,'SpecifyPosTarget');

set_param([gcb '/Body World Joint'],...
        'PxPositionTargetSpecify',sptState,...
        'PyPositionTargetSpecify',sptState,...
        'PzPositionTargetSpecify',sptState,...
        'SphPositionTargetSpecify',sptState,...
        'PxVelocityTargetSpecify',sptState,...
        'PyVelocityTargetSpecify',sptState,...
        'PzVelocityTargetSpecify',sptState...
        );

% Change rim location if wheel is on right side
if (popup_leftRight == 1)
    rhs_tire = 1;
elseif(popup_leftRight == 2)
    rhs_tire = -1;
end

Imat = [tire_inertia(1)+rim_inertia(1) 0 0; 0 tire_inertia(1)+rim_inertia(1) 0; 0 0 tire_inertia(2)+rim_inertia(2)];

