switch popup_f_axis
    case 1, vec = [ 1  0  0];
    case 2, vec = [ 0  1  0];
    case 3, vec = [ 0  0  1];
    case 4, vec = [-1  0  0];
    case 5, vec = [ 0 -1  0];
    case 6, vec = [ 0  0 -1];
end

uvec_bt = (hp_t-hp_b)/norm(hp_t-hp_b);
rotaxis = cross(vec,uvec_bt);

if (norm(rotaxis)==0)
    if (uvec_bt==0)            % hps collocated
        rotangle = 0; 
    elseif ((uvec_bt+vec)==0)  % vectors antiparallel    
        rotangle = pi;
        rotaxis = circshift(vec,1);
    else                       % vectors parallel
        rotangle = 0;          
    end
else
    rotangle = acos(dot(vec,uvec_bt));
    %rotangle = acos(dot(vec,(hp_t-hp_b)/norm((hp_t-hp_b))))
end

