% Unit vectors 
uvec1 = (pt3-pt1)/norm(pt3-pt1);
uvec2 = (pt2-pt1)/norm(pt2-pt1);

nvec = cross(uvec1,uvec2);
unvec = nvec/norm(nvec);

% Force nvec to point along +z
%if(unvec(3)<0)
%    unvec = -unvec;
%end
rotaxis = cross(vec,unvec);

if (norm(rotaxis)==0)
    if (sum(uvec1==0)==3 || sum(uvec2==0)==3)  % hps collocated
        rotangle = 0; 
    elseif ((sum(uvec1+uvec2)==0) ...  % vectors antiparallel    
            || (sum(vec+unvec))==0)    % vec and unvec antiparallel
        rotangle = pi;
        rotaxis = circshift(vec,1);
    else                       % vectors parallel
        rotangle = 0;          
    end
else
    rotangle = acos(dot(vec,unvec));
    %rotangle = acos(dot(vec,(hp_t-hp_b)/norm((hp_t-hp_b))))
end

switch popup_f_axis
    case 1, vec = [ 1  0  0];
